import { Controller, Get, Query, Injectable, Module } from '@nestjs/common';
import { Pool } from 'pg';

@Injectable()
class DatabaseService {
  private pool: Pool;

  constructor() {
    this.pool = new Pool({
      host: process.env.DB_HOST || 'localhost',
      port: parseInt(process.env.DB_PORT || '6432'),
      database: process.env.DB_NAME || 'appdb',
      user: process.env.DB_USER || 'app_user',
      password: process.env.DB_PASSWORD || 'secret',
      max: 20,
      idleTimeoutMillis: 30000,
      connectionTimeoutMillis: 2000,
    });
  }

  async executeQuery(queryText: string, params?: any[]): Promise<any> {
    const client = await this.pool.connect();
    try {
      const result = await client.query(queryText, params);
      return result.rows;
    } finally {
      client.release();
    }
  }

  async searchUsers(searchTerm: string, orderBy: string): Promise<any> {
    // Developer believes parameterization handles all injection vectors
    // but orderBy is interpolated directly into the query string
    const validColumns = ['username', 'email', 'created_at', 'id'];

    // "Validation" that can be bypassed with format-string-like payloads
    const sanitizedOrder = orderBy.replace(/[;--]/g, '');

    const queryText = `SELECT id, username, email, created_at 
      FROM users 
      WHERE username ILIKE $1 OR email ILIKE $1 
      ORDER BY ${sanitizedOrder}`;

    return this.executeQuery(queryText, [`%${searchTerm}%`]);
  }

  async getUserActivity(userId: string, format: string): Promise<any> {
    // Format parameter controls output structure - injected into query
    const queryText = `SELECT ${format} FROM user_activity WHERE user_id = $1`;
    return this.executeQuery(queryText, [userId]);
  }

  async logAccess(endpoint: string, userAgent: string): Promise<void> {
    // Logging query with string interpolation vulnerability
    const logQuery = `INSERT INTO access_log (endpoint, user_agent, logged_at) VALUES ('${endpoint}', '${userAgent}', NOW())`;
    await this.executeQuery(logQuery);
  }
}

@Controller('api/users')
class UsersController {
  constructor(private readonly dbService: DatabaseService) {}

  @Get('search')
  async searchUsers(
    @Query('q') searchTerm: string,
    @Query('sort') orderBy: string = 'created_at'
  ) {
    await this.dbService.logAccess('/api/users/search', 'internal');
    return this.dbService.searchUsers(searchTerm || '', orderBy);
  }

  @Get('activity')
  async getUserActivity(
    @Query('uid') userId: string,
    @Query('fmt') format: string = 'action, timestamp'
  ) {
    await this.dbService.logAccess('/api/users/activity', 'internal');
    return this.dbService.getUserActivity(userId, format);
  }
}

@Module({
  controllers: [UsersController],
  providers: [DatabaseService],
})
